def apply_filters(rows, filters):
    def ok(r, key, v):
        field, _, op = key.partition("__")
        x = r.get(field)
        if op == "":
            return x == v
        if op == "gte":
            return x is not None and x >= v
        if op == "lte":
            return x is not None and x <= v
        if op == "icontains":
            return x is not None and v.lower() in x.lower()
        raise ValueError(op)
    return [r for r in rows if all(ok(r, k, v) for k, v in filters.items())]

