def migration_order(deps):
    indeg = {m: len(d) for m, d in deps.items()}
    users = {m: [] for m in deps}
    for m, ds in deps.items():
        for d in ds:
            users[d].append(m)
    ready = sorted(m for m, n in indeg.items() if n == 0)
    out = []
    while ready:
        m = ready.pop()
        out.append(m)
        for u in users[m]:
            indeg[u] -= 1
            if indeg[u] == 0:
                ready.append(u)
        ready.sort()
    return out

